#include <string>
#include <string_view>

std::string build_message(std::string_view begin,
                          std::string_view symbol,
                          std::string_view price,
                          std::string_view checksum) {
    std::string message;
    message.reserve(begin.size() + symbol.size() +
                    price.size() + checksum.size());

    // `begin + symbol + price + checksum` would instead create three
    // temporary string results, each of which can acquire capacity.
    message.append(begin);
    message.append(symbol);
    message.append(price);
    message.append(checksum);
    return message;
}

#include <string_view>

std::string_view next_field(std::string_view& message, char separator) {
    if (message.empty()) {
        return {};
    }

    const std::size_t position = message.find(separator);
    const std::string_view field = message.substr(0, position);

    if (position == std::string_view::npos) {
        message = {};  // consumed the last field
    } else {
        message.remove_prefix(position + 1);
    }
    return field;
}

#include <string>
#include <string_view>

extern "C" void send_symbol(const char*);

void forward(std::string_view symbol) {
    // symbol.data() is not usable here: a view's end is recorded by its
    // length, not by a terminator, so the C function would read past the
    // logical end -- out of bounds, or silently the wrong text if some
    // later zero byte happens to stop it.
    const std::string terminated{symbol};  // copies; may allocate
    send_symbol(terminated.c_str());
}

