#include <string>
#include <string_view>
#include <utility>

class Order {
public:
    // The old member was a std::string_view over the by-value parameter,
    // which is a local object destroyed when the constructor returns: every
    // Order was dangling before it was ever used. A class built from a
    // by-value std::string must store its own std::string.
    explicit Order(std::string symbol) : symbol_(std::move(symbol)) {}

    std::string_view symbol() const { return symbol_; }

private:
    std::string symbol_;
};

#include <cstddef>
#include <span>
#include <utility>

int checksum(std::span<const std::byte> message) {
    int total = 0;
    for (std::byte value : message) {
        total += std::to_integer<int>(value);
    }
    return total;
}

using Split = std::pair<std::span<const std::byte>,
                        std::span<const std::byte>>;

Split split_header(std::span<const std::byte> message) {
    if (message.size() < 4) {
        return {message, {}};
    }
    return {message.first(4), message.subspan(4)};
}

#include <charconv>
#include <cstdint>
#include <optional>
#include <string_view>

std::optional<std::int64_t> parse_quantity(std::string_view field) {
    if (field.empty()) {
        return std::nullopt;
    }

    std::int64_t quantity = 0;
    const char* const end = field.data() + field.size();
    const auto [next, error] =
        std::from_chars(field.data(), end, quantity);

    if (error != std::errc{}) {
        return std::nullopt;  // invalid_argument or result_out_of_range
    }
    if (next != end) {
        return std::nullopt;  // trailing characters
    }
    return quantity;
}
